adding\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"30\",\"bottom\":\"30\",\"left\":\"30\",\"isLinked\":true},\"_flex_align_self\":\"center\",\"_title\":\"domaine\",\"flex_gap\":{\"column\":\"0\",\"row\":\"0\",\"isLinked\":true,\"unit\":\"px\",\"size\":0},\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"211a8fa\",\"elType\":\"widget\",\"settings\":{\"title\":\"Abstact\",\"align_mobile\":\"center\",\"typography_typography\":\"custom\",\"typography_font_size_mobile\":{\"unit\":\"px\",\"size\":15,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"a006078\",\"elType\":\"widget\",\"settings\":{\"align\":\"left\",\"align_mobile\":\"center\"},\"elements\":[],\"widgetType\":\"theme-post-content\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false}]'),(3207,758,'_elementor_conditions','a:1:{i:0;s:21:\"include/singular/post\";}'),(3208,758,'_elementor_page_assets','a:2:{s:7:\"scripts\";a:2:{i:0;s:15:\"hfe-frontend-js\";i:1;s:18:\"elementor-frontend\";}s:6:\"styles\";a:6:{i:0;s:14:\"widget-heading\";i:1;s:12:\"widget-image\";i:2;s:16:\"widget-post-info\";i:3;s:16:\"widget-icon-list\";i:4;s:26:\"elementor-icons-fa-regular\";i:5;s:24:\"elementor-icons-fa-solid\";}}'),(3209,758,'_elementor_css','a:6:{s:4:\"time\";i:1762957929;s:5:\"fonts\";a:0:{}s:5:\"icons\";a:2:{i:0;s:8:\"fa-solid\";i:1;s:10:\"fa-regular\";}s:20:\"dynamic_elements_ids\";a:2:{i:0;s:7:\"8694dc2\";i:1;s:7:\"c20b75e\";}s:6:\"status\";s:4:\"file\";i:0;s:0:\"\";}'),(3210,758,'_elementor_element_cache','{\"timeout\":1763044329,\"value\":{\"content\":\"<div class=\"elementor-element elementor-element-713f1e76 e-con-full e-flex e-con e-parent\" data-id=\"713f1e76\" data-element_type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;}\">ntt<div class=\"elementor-element elementor-element-34103c4 e-con-full e-flex e-con e-child\" data-id=\"34103c4\" data-element_type=\"container\" data-settings=\"{&qu