,'Acceuil','','inherit','closed','closed','','418-revision-v1','','','2025-10-04 11:22:42','2025-10-04 11:22:42','',418,'http://localhost:8080/?p=421',0,'revision','',0),(422,1,'2025-10-04 11:22:43','2025-10-04 11:22:43','Add Your Heading Text Here','Acceuil','','inherit','closed','closed','','418-revision-v1','','','2025-10-04 11:22:43','2025-10-04 11:22:43','',418,'http://localhost:8080/?p=422',0,'revision','',0),(424,1,'2025-10-04 11:34:05','2025-10-04 11:34:05','','Default Kit','','inherit','closed','closed','','214-revision-v1','','','2025-10-04 11:34:05','2025-10-04 11:34:05','',214,'http://localhost:8080/?p=424',0,'revision','',0),(425,1,'2025-10-04 11:34:41','2025-10-04 11:34:41','','Default Kit','','inherit','closed','closed','','214-revision-v1','','','2025-10-04 11:34:41','2025-10-04 11:34:41','',214,'http://localhost:8080/?p=425',0,'revision','',0),(426,1,'2025-10-04 11:43:38','0000-00-00 00:00:00','Thank you for reading this post, don\'t forget to subscribe!','Display a message after the 1st paragraph of posts','','draft','closed','closed','','','','','2025-10-04 11:43:38','0000-00-00 00:00:00','',0,'http://localhost:8080/?post_type=wpcode&p=426',0,'wpcode','',0),(427,1,'2025-10-04 11:43:39','0000-00-00 00:00:00','add_action(\'admin_init\', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === \'edit-comments.php\') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});','Completely Disable Comments','','draft','closed','closed','','','','','2025-10-04 11:43:39','0000-00-00 00:00:00','',0,'http://localhost:8080/?post_type=wpcode&p=427',0,'wpcode','',0),(428,1,'2025-10-04 11:48:31','2025-10-04 11:48:31','function current_date_shortcode() {\r\n    return date_i18n(\'Y\');\r\n}\r\nadd_shortcode(\'current_date\', \'current_date_shortcode\');','Current date','','publish','closed','closed','','untitled-snippet','','','2025-11-10 12:04:51','2025-11-10 12:04:51','',0,'http://localhost:8080/wpcode/untitled-snippet/',0,'wpcode','',0),(429,1,'2025-10-04 11:50:01','2025-10-04 11:50:01','Add Your Heading Text Here','Acceuil','','inherit','closed','closed','','418-revision-v1','','','2025-10-04 11:50:01','2025-10-04 11:50:01','',418,'http://localhost:8080/?p=429',0,'revision','',0),(430,1,'2025-10-04 11:50:02','2025-10-04 11:50:02','Add Your Heading Text Here','Acceuil','','inherit','closed','closed','','418-revision-v1','','','2025-10-04 11:50:02','2025-10-04 11:50:02','',418,'http://localhost:8080/?p=430',0,'revision','',0),(431,1,'2025-10-04 11:50:03','2025-10-04 11:50:03','Date du jour : [current_date]','Acceuil','','inherit','closed','closed','','418-revision-v1','','','2025-10-04 11:50:03','2025-10-04 11:50:03','',418,'http://localhost:8080/?p=431',0,'revision','',0),(433,1,'2025-10-04 12:18:21','2025-10-04 12:14:31','','Login','','publish','closed',