,'2025-10-05 11:21:16','2025-10-05 11:21:16','',214,'http://localhost:8080/?p=582',0,'revision','',0),(584,1,'2025-10-05 18:15:49','2025-10-05 18:15:49','function cdnss_select_shortcode($atts) {\r\n    $atts = shortcode_atts(array(\r\n        \'options\' => \'Option 1, Option 2, Option 3\', // Default fallback\r\n        \'width\'   => \'100%\',\r\n    ), $atts, \'cdnss_select\');\r\n\r\n    $options = explode(\',\', $atts[\'options\']);\r\n\r\n    ob_start(); ?>\r\n\r\n    <style>\r\n    .cdnss-select {\r\n      position: relative;\r\n      width: <?php echo esc_attr($atts[\'width\']); ?>;\r\n    }\r\n\r\n    .cdnss-select select {\r\n      width: 100%;\r\n      padding: 10px 15px;\r\n      font-size: 14px;\r\n      border: 1px solid #ccc;\r\n      border-radius: 10px;\r\n      background-color: #fff;\r\n      appearance: none;\r\n      -webkit-appearance: none;\r\n      -moz-appearance: none;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n    }\r\n\r\n   \r\n\r\n    \r\n    </style>\r\n\r\n    <div class=\"cdnss-select\">\r\n      <select>\r\n        <?php foreach ($options as $option): ?>\r\n          <option><?php echo trim($option); ?></option>\r\n        <?php endforeach; ?>\r\n      </select>\r\n    </div>\r\n\r\n    <?php\r\n    return ob_get_clean();\r\n}\r\nadd_shortcode(\'cdnss_select\', \'cdnss_select_shortcode\');\r\n','cdnss select','','publish','closed','closed','','cdnss-select','','','2025-10-05 18:24:35','2025-10-05 18:24:35','',0,'http://localhost:8080/?post_type=wpcode&#038;p=584',0,'wpcode','',0),(585,1,'2025-10-05 18:33:43','2025-10-05 18:33:43','','RECHERCHES AVANCEES','','inherit','closed','closed','','490-revision-v1','','','2025-10-05 18:33:43','2025-10-05 18:33:43','',490,'http://localhost:8080/?p=585',0,'revision','',0),(586,1,'2025-10-05 18:33:45','2025-10-05 18:33:45','','RECHERCHES AVANCEES','','inherit','closed','closed','','490-revision-v1','','','2025-10-05 18:33:45','2025-10-05 18:33:45','',490,'http://localhost:8